using System;using System.IO;using System.Collections.Generic;using System.Threading;using System.Web.Script.Serialization;using System.Reflection;
internal static class HostResourcesRegression {
 static void Need(bool ok,string message){if(!ok)throw new Exception(message);}
 public static int Main(string[] args){if(args[0]=="--inspect"){string dir=AppDomain.CurrentDomain.BaseDirectory;bool ok=File.Exists(Path.Combine(dir,"jlwpengine.resc"))&&File.Exists(Path.Combine(dir,"jlwpengine2.resc"))&&File.Exists(Path.GetFullPath(Path.Combine(dir,"..","..","rules","runtime-components.json")));File.WriteAllText(args[1],new JavaScriptSerializer().Serialize(new{passed=ok,image=typeof(HostResourcesRegression).Assembly.Location,resourcesReadByImageDirectory=true,nativeLoaded=false}));return ok?0:1;}string run=Path.GetFullPath(args[0]),report=args[1];var result=new Dictionary<string,object>();var cases=new List<string>();try{
  Directory.CreateDirectory(run);string own=typeof(HostResourcesRegression).Assembly.Location;string baseDir=Path.Combine(run,"package","build","runtime"),rules=Path.Combine(run,"package","rules"),ext=Path.Combine(run,"inert-components");Directory.CreateDirectory(baseDir);Directory.CreateDirectory(rules);Directory.CreateDirectory(ext);string host=Path.Combine(baseDir,"Desktop317495Host-refined.exe");File.Copy(own,host);string hostHash=Hash(host);var files=new Dictionary<string,string>();var rows=new List<object>();rows.Add(new{name="Desktop317495Host-refined.exe",sha256=hostHash});for(int i=0;i<23;i++){string name=i==0?"jlwpengine.resc":i==1?"jlwpengine2.resc":"inert-"+i+".dll";string p=Path.Combine(ext,name);File.WriteAllText(p,"Self-owned inert fixture "+name);files.Add(name,p);rows.Add(new{name=name,sha256=Hash(p)});}string contract=Path.Combine(rules,"runtime-components.json");File.WriteAllText(contract,new JavaScriptSerializer().Serialize(new{files=rows}));string contractHash=Hash(contract);
#if LEGACY_R19
  // The captured R19 deployment uses the shipped host image directory, with
  // no resource staging. Reproduce that exact missing-archive precondition.
  Need(File.Exists(Path.Combine(baseDir,"jlwpengine.resc"))&&File.Exists(Path.Combine(baseDir,"jlwpengine2.resc")),"R19 host image directory lacks both contract-required resource archives; captured native log reports these exact paths missing");
#else
  string r=Path.Combine(run,"first-run");Directory.CreateDirectory(r);var stage=HostResources.Stage(r,host,contract,contractHash,hostHash,files,CancellationToken.None);Need(Hash(stage.Image)==hostHash,"host hash");Need(Hash(stage.Contract)==contractHash,"contract hash");Need(Path.GetFullPath(Path.Combine(Path.GetDirectoryName(stage.Image),"..","..","rules","runtime-components.json"))==stage.Contract,"host relative contract location");foreach(string name in HostResources.Archives)Need(Hash(Path.Combine(Path.GetDirectoryName(stage.Image),name))==Hash(files[name]),"archive beside actual host");Need(Directory.GetFiles(Path.GetDirectoryName(stage.Image)).Length==3,"only host and two archives staged, no DLLs");cases.Add("archives-beside-host-contract-relative-layout");
  // Run a new, console-only fixture image from the staged host location. It
  // reads resources by its actual image directory, then exits without UI/native calls.
  string childReport=Path.Combine(run,"child.json");var si=new System.Diagnostics.ProcessStartInfo(stage.Image,"--inspect \""+childReport+"\""){UseShellExecute=false,CreateNoWindow=true};using(var child=System.Diagnostics.Process.Start(si)){Need(child.WaitForExit(10000),"fixture child exceeded 10s; left untouched");Need(child.ExitCode==0,"new child failed resource location check");result["childPid"]=child.Id;result["childNormalExit"]=true;}Need(File.Exists(childReport),"child receipt missing");cases.Add("new-process-reads-resources-by-image-directory");
  bool rejected=false;try{HostResources.Stage(r,host,contract,contractHash,hostHash,files,CancellationToken.None);}catch(IOException){rejected=true;}Need(rejected,"existing stage overwritten");cases.Add("existing-stage-rejected");stage.Cleanup();Need(!Directory.Exists(stage.Root),"stage not cleaned");stage.Cleanup();cases.Add("normal-cleanup-idempotent");
  var nested=Path.Combine(ext,"depdlls");Directory.CreateDirectory(nested);foreach(string name in HostResources.Archives){File.Move(files[name],Path.Combine(nested,name));files[name]=Path.Combine(nested,name);}string nr=Path.Combine(run,"nested-run");Directory.CreateDirectory(nr);var nestedStage=HostResources.Stage(nr,host,contract,contractHash,hostHash,files,CancellationToken.None);nestedStage.Cleanup();cases.Add("verified-nested-source-layout");
  string bad=files["jlwpengine2.resc"],before=File.ReadAllText(bad);File.WriteAllText(bad,"changed");string fr=Path.Combine(run,"failed-run");Directory.CreateDirectory(fr);rejected=false;try{HostResources.Stage(fr,host,contract,contractHash,hostHash,files,CancellationToken.None);}catch(InvalidDataException){rejected=true;}Need(rejected&&!Directory.Exists(Path.Combine(fr,"host")),"changed resource accepted or partial stage remains");File.WriteAllText(bad,before);cases.Add("changed-resource-rejected-partial-cleaned");
  string cr=Path.Combine(run,"cancel-run");Directory.CreateDirectory(cr);var c=new CancellationTokenSource();c.Cancel();rejected=false;try{HostResources.Stage(cr,host,contract,contractHash,hostHash,files,c.Token);}catch(OperationCanceledException){rejected=true;}Need(rejected&&!Directory.Exists(Path.Combine(cr,"host")),"cancel created stage");cases.Add("cancel-before-stage-no-files");
  string ur=Path.Combine(run,"unknown-run");Directory.CreateDirectory(ur);var unknown=HostResources.Stage(ur,host,contract,contractHash,hostHash,files,CancellationToken.None);string unexpected=Path.Combine(unknown.Root,"unexpected.txt");File.WriteAllText(unexpected,"preserve evidence");rejected=false;try{unknown.Cleanup();}catch(IOException){rejected=true;}Need(rejected&&File.Exists(unexpected)&&File.Exists(unknown.Image),"unexpected cleanup destroyed evidence");File.Delete(unexpected);unknown.Cleanup();cases.Add("unknown-files-preserved-cleanup-retry");
  string wr=Path.Combine(run,"wrong-contract-run");Directory.CreateDirectory(wr);rejected=false;try{HostResources.Stage(wr,host,contract,new string('0',64),hostHash,files,CancellationToken.None);}catch(InvalidDataException){rejected=true;}Need(rejected&&!Directory.Exists(Path.Combine(wr,"host")),"bad contract created stage");cases.Add("contract-identity-rejected");
#endif
  result["passed"]=true;
 }catch(Exception ex){result["passed"]=false;result["error"]=ex.ToString();}result["cases"]=cases;result["thirdPartyModulesLoaded"]=false;result["guiOpened"]=false;result["scope"]="resource-location precondition and actual staging processor with inert fixtures; does not prove rendered pixels";Directory.CreateDirectory(Path.GetDirectoryName(report));File.WriteAllText(report,new JavaScriptSerializer().Serialize(result));return (bool)result["passed"]?0:1;}
 static string Hash(string p){using(var s=File.OpenRead(p))using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
}
